function runningMedian(nums) {
  const low = [], high = [], medians = [] //@init
  for (const x of nums) {
    if (!low.length || x <= low[0]) push(low, x, bigger) //@choose
    else push(high, x, smaller)
    if (low.length > high.length + 1) push(high, pop(low, bigger), smaller) //@balance
    else if (high.length > low.length) push(low, pop(high, smaller), bigger)
    medians.push(low.length > high.length ? low[0] : (low[0] + high[0]) / 2) //@median
  }
  return medians //@done
}

// low is a max-heap (bigger values on top); high is a min-heap.
const bigger = (a, b) => a > b
const smaller = (a, b) => a < b

function push(h, x, before) {
  h.push(x)
  let i = h.length - 1
  while (i > 0 && before(h[i], h[(i - 1) >> 1])) {
    const p = (i - 1) >> 1
    ;[h[i], h[p]] = [h[p], h[i]]
    i = p
  }
}

function pop(h, before) {
  const top = h[0]
  const last = h.pop()
  if (h.length) {
    h[0] = last
    let i = 0
    for (;;) {
      let s = i
      for (const c of [2 * i + 1, 2 * i + 2]) if (c < h.length && before(h[c], h[s])) s = c
      if (s === i) break
      ;[h[i], h[s]] = [h[s], h[i]]
      i = s
    }
  }
  return top
}

