declare function push(h: number[], x: number, before: Before): void
declare function pop(h: number[], before: Before): number

class MedianFinder {
  low: number[] = [] // max-heap of the smaller half
  high: number[] = [] // min-heap of the larger half

  add(x: number): void {
    const bigger: Before = (a, b) => a > b
    const smaller: Before = (a, b) => a < b
    if (!this.low.length || x <= this.low[0]) push(this.low, x, bigger)
    else push(this.high, x, smaller)
    if (this.low.length > this.high.length + 1) push(this.high, pop(this.low, bigger), smaller)
    else if (this.high.length > this.low.length) push(this.low, pop(this.high, smaller), bigger)
  }

  median(): number {
    if (this.low.length > this.high.length) return this.low[0]
    return (this.low[0] + this.high[0]) / 2
  }
}

